def transform_v2(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    # First pass: handle non-4s
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color != 4:
                # Count same-color orthogonal neighbors
                neighbor_count = 0
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == color:
                            neighbor_count += 1

                # Keep if >= 2 neighbors
                if neighbor_count >= 2:
                    result[r][c] = color
                else:
                    result[r][c] = 9
            # 4s are left unchanged for now

    # Second pass: handle 4s
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                # Find majority in 3x3 block (excluding background)
                counts = {}
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 9:
                                counts[grid[nr][nc]] = counts.get(grid[nr][nc], 0) + 1

                if counts:
                    majority = max(counts, key=counts.get)
                    result[r][c] = majority
                else:
                    result[r][c] = 9

    return result

