from collections import defaultdict, deque

def get_components_and_peerhood(grid, num_rows, num_cols, peerhood_threshold=2):
    """
    Get 4-connected components and their average peerhood.
    A cell is kept if its component's peerhood > threshold,
    OR if that component has at least one cell with peerhood > threshold.
    """
    visited = [[False] * num_cols for _ in range(num_rows)]
    comp_data = defaultdict(list)  # color -> list of (component_id, cells)

    comp_id = 0
    for r in range(num_rows):
        for c in range(num_cols):
            color = grid[r][c]
            if color == 4 or visited[r][c]:
                continue
            component = []
            queue = [(r,c)]
            visited[r][c] = True
            while queue:
                cr, cc = queue.pop(0)
                component.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < num_rows and 0 <= nc < num_cols:
                        if not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

            # Compute peerhoods for this component
            total_peerhood = 0
            component_ids = 0
            cells_with_high_peerhood = []

            for cr, cc in component:
                peerhood = 0
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < num_rows and 0 <= nc < num_cols:
                        if grid[nr][nc] == color:
                            peerhood += 1
                total_peerhood += peerhood
                if peerhood > peerhood_threshold:
                    cells_with_high_peerhood.append((cr, cc))
                cells_with_high_peerhood.append((cr, cc, peerhood))

            comp_id += 1
            comp_data[color].append({
                'id': comp_id - 1,
                'cells': component,
                'total_peerhood': total_peerhood / len(component),
                'max_peerhood': max(p for _,_,p in cells_with_high_peerhood),
                'has_high_peerhood_cell': len(cells_with_high_peerhood) > 0 and any(p > peerhood_threshold for _,_,p in cells_with_high_peerhood)
            })

    return comp_data

