def get_components_with_position(grid, num_rows, num_cols):
    """Get components and determine if cells are on edge"""
    visited = [[False] * num_cols for _ in range(num_rows)]
    comps = defaultdict(list)

    for r in range(num_rows):
        for c in range(num_cols):
            color = grid[r][c]
            if color == 4 or visited[r][c]:
                continue
            component = []
            queue = deque([(r,c)])
            visited[r][c] = True
            while queue:
                cr, cc = queue.popleft()
                component.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < num_rows and 0 <= nc < num_cols and \
                       not visited[nr][nc] and grid[nr][nc] == color:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
            comps[color].append(component)

    return comps

